# 5. జలియన్‌వాలా బాగ్ (te5) – Telugu_01T.pdf పేజీలు 23–25
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
from qbh import Bank, AR, PY, PV, NN, SD, SM, VY
B = Bank(5, 'te5'); q, m = B.q, B.mcq
PP = 'కింది పద్యానికి ప్రతిపదార్థాలు రాయండి.\n'
q(1, 8, PP + 'యూరపు దేశ మెక్కడల హూణకిరాటపుళిందు లేదె? యా\nఘోరరణంబునం దరులఁ గూల్చి జయధ్వజ మెత్తినట్టి మా\nభారతవీరయోధు లొక పాటె నిరంకుశ శాసనాగ్ని సం\nస్కారముచేసినారు; సిత జాతికి నీతియటంచు నున్నదే.',
  'ప్రతిపదార్థం (ముఖ్య పదాలు):\nయూరపు దేశము = యూరప్ ఖండంలో\nహూణ = ఆంగ్లేయుల\nకిరాట = కిరీటం (రాజ్యాధికారం) నిలవడానికి\nఆ ఘోరరణంబునన్ = ఆ భయంకరమైన (మొదటి ప్రపంచ) యుద్ధంలో\nఅరులన్ = శత్రువులను\nకూల్చి = చంపి\nజయధ్వజము = విజయపతాకాన్ని\nఎత్తినట్టి = ఎగురవేసిన\nమా భారతవీరయోధులు = మా భారతదేశ వీర సైనికులు\nఒక పాటె = ఒక లెక్కా? (వారికి ఏమాత్రం విలువ లేదా?)\nనిరంకుశ శాసన + అగ్నిన్ = అదుపులేని (క్రూరమైన) చట్టమనే అగ్నిలో\nసంస్కారము చేసినారు = దహనం చేశారు (వారిని బలి చేశారు)\nసితజాతికిన్ = తెల్లజాతికి (ఆంగ్లేయులకు)\nనీతి + అటంచున్ = నీతి అనేది\nఉన్నదే = ఉన్నదా? (లేదు)\nభావం: యూరప్‌లో జరిగిన ఘోర యుద్ధంలో ఆంగ్లేయుల కిరీటం కోసం శత్రువులను కూల్చి విజయపతాకం ఎగురవేసిన మా భారత వీర సైనికులు వారికి ఒక లెక్కే కాదా? వారిని నిరంకుశ (రౌలట్) చట్టమనే అగ్నిలో దహించారు. తెల్లజాతికి నీతి అనేది ఉందా?\n(మొదటి పాదంలోని పదవిభజనను పాఠ్యపుస్తకంతో సరిచూసుకోండి.)')
q(1, 8, 'జలియన్‌వాలా బాగ్ దురంతాన్ని సవివరంగా తెలపండి.',
  '• 1919 ఏప్రిల్ 13 – వైశాఖీ పండుగ రోజు, పంజాబ్‌లోని అమృత్‌సర్ నగరంలో జలియన్‌వాలా బాగ్ అనే తోటలో నిరంకుశమైన రౌలట్ చట్టానికి నిరసనగా శాంతియుత సభ జరిగింది.\n• ఆ తోటకు ఒకే ఒక ఇరుకైన ప్రవేశ మార్గం; నలువైపులా ఎత్తైన గోడలు.\n• స్త్రీలు, పిల్లలు, వృద్ధులు సహా వేలాది నిరాయుధ ప్రజలు అక్కడ చేరారు.\n• జనరల్ డయ్యర్ సైన్యంతో వచ్చి ఏ హెచ్చరికా లేకుండా ప్రజలపై కాల్పులు జరిపించాడు; సుమారు 1650 రౌండ్లు కాల్చారు.\n• తప్పించుకునే దారి లేక ప్రజలు పిట్టల్లా రాలిపోయారు; ప్రాణభయంతో చాలామంది బావిలో దూకారు; వందలాది మంది మరణించారు, వేలాది మంది గాయపడ్డారు.\n• ఈ దురంతం దేశమంతటా ఆగ్రహం రగిలించింది; రవీంద్రనాథ్ ఠాగూర్ తన ‘సర్’ బిరుదును త్యజించారు; స్వాతంత్ర్యోద్యమం ఉధృతమైంది.\n• కవి ఉమర్ ఆలీషా ఈ ఘటనను ఆవేదనతో వర్ణిస్తూ – మొదటి ప్రపంచ యుద్ధంలో ఆంగ్లేయుల కోసం ప్రాణాలొడ్డి పోరాడిన భారతీయులకు బహుమతిగా రౌలట్ చట్టం, కాల్పులు ఇచ్చారని, ఈ పాపం ఊరికే పోదని హెచ్చరించాడు.')
q(1, 8, 'మీకు నచ్చిన స్వాతంత్ర్య సమరయోధుడిని ప్రశంసిస్తూ అభినందన పత్రం రాయండి.',
  '🌸 అభినందన పత్రం 🌸\nమన్యం వీరుడు శ్రీ అల్లూరి సీతారామరాజు గారికి –\n• విశాఖ మన్యం ప్రాంతంలో ఆంగ్లేయుల దోపిడీ, అటవీ చట్టాల అన్యాయాలకు బలవుతున్న గిరిజనులను మీరు ఏకం చేశారు.\n• విల్లంబులు, సంప్రదాయ ఆయుధాలతోనే ఆధునిక ఆయుధాలు గల బ్రిటిష్ సైన్యాన్ని గడగడలాడించారు; పోలీస్ స్టేషన్లపై దాడి చేసి ఆయుధాలు స్వాధీనం చేసుకున్నారు (రంప తిరుగుబాటు 1922–24).\n• చిన్న వయసులోనే దేశం కోసం ప్రాణాలర్పించిన మీ త్యాగం, ధైర్యం, సంకల్పం ప్రతి భారతీయునికి స్ఫూర్తి.\n• మీరు చూపిన దేశభక్తి మార్గంలో నడుస్తామని, దేశ సేవకు పాటుపడతామని ప్రతిజ్ఞ చేస్తున్నాం.\nమీ పాదపద్మాలకు శతకోటి వందనాలు.\nఇట్లు,\nవిద్యార్థులు, జిల్లా పరిషత్ ఉన్నత పాఠశాల, టి.వి. పల్లి, గూడూరు మండలం, SPSR నెల్లూరు జిల్లా.')
q(1, 4, 'జలియన్‌వాలాబాగ్ పాఠ్యాంశ కవి గురించి రాయండి.',
  '• కవి: కవిశేఖర డా. ఉమర్ ఆలీషా (28.02.1885 – 23.01.1945).\n• జన్మస్థలం: పిఠాపురం (కాకినాడ జిల్లా); తల్లిదండ్రులు: చాంద్‌బీబీ, మొహియుద్దీన్ బాద్షా.\n• మహాకవి, వక్త, అవధాని, ఆధ్యాత్మికవేత్త, బహుభాషా పండితుడు; పార్లమెంటు సభ్యునిగా కూడా పనిచేశారు; ఆధ్యాత్మిక పీఠం ‘జ్ఞానసభ’.\n• రచనలు: మణిమాల, అనసూయాదేవి, చంద్రగుప్త (నాటకాలు); బ్రహ్మవిద్యా విలాసం, సూఫీ వేదాంత దర్శనం మొదలైనవి.\n• బిరుదులు: కవిశేఖర, పండిట్, మౌల్వీ; అమెరికా అంతర్జాతీయ అకాడమీ నుండి గౌరవ డాక్టరేట్.\n• ఈ పాఠం వారి ‘ఖండ కావ్యములు’ గ్రంథం నుండి గ్రహించబడింది.')
m(1, 'కురుక్షేత్ర సంగ్రామంలో రుధిరం ఏరులై పారింది. (గీత గీసిన పదం: సంగ్రామం) అర్థం గుర్తించండి.', ['రక్తం', 'ఖడ్గం', 'యుద్ధం', 'మరణం'], 2, mk=2)
m(1, 'వర్షాలు లేక పంటలు పండక కాటకం విలయ తాండవం చేస్తుంది. (గీత గీసిన పదం: కాటకం) అర్థం గుర్తించండి.', ['కాలం', 'అతివృష్టి', 'అనావృష్టి', 'కీటకం'], 2, 'కాటకం = కరువు (వర్షాభావం వల్ల).', mk=2)
for w, a in [('సితజాతి', 'తెల్లజాతి (ఆంగ్లేయులు)'), ('తులువ', 'దుష్టుడు, నీచుడు')]:
    q(1, 2, f'‘{w}’ {AR}', a)
m(1, 'సమస్త ప్రాణులకు ఉదకం ఎంతో అవసరం. (గీత గీసిన పదం: ఉదకం) పర్యాయపదాలు గుర్తించండి.', ['నీరు, జలం', 'ఉదరం, కడుపు', 'సముద్రం, జలధి', 'నది, వాహిని'], 0, mk=2)
m(1, 'అమెరికా ఇరాన్ మధ్య రణం కారణంగా ఎంతో మంది మరణించారు. (గీత గీసిన పదం: రణం) పర్యాయపదాలు గుర్తించండి.', ['ప్రాణం, ఆయువు', 'యుద్ధం, సమరం', 'బాంబులు, కత్తులు', 'సైనికులు, పోరు'], 1, mk=2)
for w, a in [('పయోధరం', 'మేఘం, మబ్బు, జలధరం, ఘనం'), ('ఆర్తి', 'బాధ, దుఃఖం, వేదన')]:
    q(1, 2, f'‘{w}’ {PY}', a)
m(1, 'విలువిద్దెలో కిరీటికి సాటిలేరు. (గీత గీసిన పదం: విద్దె) ప్రకృతి పదం గుర్తించండి.', ['మిద్య', 'విద్య', 'విదియ', 'చదువు'], 1, mk=2)
m(1, 'కబంధుడు అనే రాక్షసుడు రామలక్ష్మణుల మీదికి దూకాడు. (గీత గీసిన పదం: రాక్షసుడు) వికృతి పదం గుర్తించండి.', ['రావణుడు', 'నీచుడు', 'రక్కసుడు', 'మారీచుడు'], 2, mk=2)
for w, a in [('చండిక', 'చండిక (ప్రకృతి) – చండి (వికృతి)'), ('దోషి', 'దోషి (ప్రకృతి) – దోసి (వికృతి)')]:
    q(1, 2, f'‘{w}’ {PV}', a)
m(1, 'నేడు పెద్ద పట్టణాల్లో గజం భూమి వేల రూపాయల ఖరీదు చేస్తున్నది. (గీత గీసిన పదం: గజం) నానార్థాలు గుర్తించండి.', ['ఏనుగు, హస్తము', 'మూడు అడుగుల కొలత, ఏనుగు', 'ఏనుగు, కేసరి', 'మూర, బార'], 1, mk=2)
m(1, 'ప్రహ్లాదుడు హరి నామస్మరణ చేసేవాడు. (గీత గీసిన పదం: హరి) నానార్థాలు గుర్తించండి.', ['విష్ణువు, చక్రం', 'శివుడు, ఇంద్రుడు', 'విష్ణువు, కోతి', 'విష్ణువు, శివుడు'], 2, 'హరి = విష్ణువు, కోతి, సింహం, ఇంద్రుడు, గుర్రం.', mk=2)
for s, j, a in [('యుద్ధంలో వీరులు వెన్నుచూపు చూపడం ఓటమికి సంకేతం.', 'వెన్నుచూపు', 'భయపడి పారిపోవడం (ఓటమిని అంగీకరించడం)'), ('కొందరికి అమాయకులను మోసం చేయడం ఉగ్గుపాలతో పెట్టిన విద్య.', 'ఉగ్గుపాలతో పెట్టిన విద్య', 'చిన్నతనం నుంచే బాగా అలవాటైన పని'), ('ప్రయత్నం చేయకుండా ఫలితం కోసం అంగలార్చరాదు.', 'అంగలార్చు', 'అత్యాశతో ఆరాటపడడం / బాధపడడం')]:
    q(1, 2, f'జాతీయాన్ని గుర్తించి, విడిగా రాసి అర్థం తెలపండి: “{s}”', f'జాతీయం: {j} – {a}.')
m(1, 'అనవసరపు వాగ్వాదం మంచిది కాదు. (గీత గీసిన పదం: వాగ్వాదం) విడదీసి గుర్తించండి.', ['వాగ్ + వాదం', 'వాక్ + యుద్ధం', 'వాక్ + వాదం', 'వాక్ + వివాదం'], 2, 'వాక్ + వాదం – జశ్త్వ సంధి.')
m(1, 'కింది పదాలలో సరళాదేశ సంధికి చెందిన పదాన్ని గుర్తించండి.', ['జగన్మాత', 'రణంబిది', 'అజంతం', 'పాలుఁజేసి'], 3, 'పాలు + చేసి = పాలుఁజేసి – సరళాదేశ సంధి (ద్రుత ప్రకృతికాలపై పరుషాలకు సరళాలు).')
m(1, 'శివాజీ శత్రువులపై ధ్వజమెత్తి విజయం సాధించాడు. (గీత గీసిన పదం: ధ్వజమెత్తి) ఏ సంధి?', ['అత్వ సంధి', 'గుణ సంధి', 'ఉత్వ సంధి', 'ఇత్వ సంధి'], 2, 'ధ్వజము + ఎత్తి – ఉత్వ సంధి.')
for w, a in [('ఉద్యద్భక్తి', 'ఉద్యత్ + భక్తి – జశ్త్వ సంధి'), ('హృద్ద్వారం', 'హృత్ + ద్వారం – జశ్త్వ సంధి')]:
    q(1, 1, f'‘{w}’ {SD}', a)
m(1, 'శౌర్యపరాక్రమములు విజేతకు అలంకారాలు. (గీత గీసిన పదం: శౌర్యపరాక్రమములు) విగ్రహవాక్యం గుర్తించండి.', ['శౌర్యంతో పరాక్రమం', 'శౌర్యం వలన పరాక్రమం', 'శౌర్యం యొక్క పరాక్రమం', 'శౌర్యమును, పరాక్రమమును'], 3, 'ద్వంద్వ సమాసం.')
m(1, 'ఘోరరణం వలన ప్రజలు నష్టపోతారు. (గీత గీసిన పదం: ఘోరరణం) ఏ సమాసం?', ['విశేషణ పూర్వపద కర్మధారయ సమాసం', 'చతుర్థీ తత్పురుష సమాసం', 'తృతీయా తత్పురుష సమాసం', 'ప్రథమా తత్పురుష సమాసం'], 0, 'ఘోరమైన రణం.')
for w, a in [('శుద్ధాంతకాంత', 'శుద్ధాంతము నందలి కాంత – సప్తమీ తత్పురుష సమాసం'), ('పాపఫలం', 'పాపము యొక్క ఫలం – షష్ఠీ తత్పురుష సమాసం'), ('దేహపంజరం', 'దేహమనెడి పంజరం – రూపక సమాసం'), ('రాకాసిమూక', 'రాకాసుల యొక్క మూక – షష్ఠీ తత్పురుష సమాసం')]:
    q(1, 1, f'‘{w}’ {SM}', a)
# ══ LEVEL-2 ══
q(2, 8, PP + 'ప్రళయపయోదముల్ గురియు భంగి ఫరంగి ఫిరంగిగుండ్ల గుం\nడెలదర దేహపంజరము డిల్లగ జల్లెడరీతి మార్చినన్\nసొలసియు నిస్సురుస్సురని స్రుక్కఁడు చిక్కఁడు వైరిచేతికిన్\nబలవదరిప్రభంజనుఁడు భారతవీరుఁడు మాటలేటికిన్.',
  'ప్రతిపదార్థం:\nప్రళయ పయోదముల్ = ప్రళయకాలపు మేఘాలు\nకురియు భంగిన్ = వర్షించే విధంగా\nఫరంగి = ఆంగ్లేయుల\nఫిరంగి గుండ్లన్ = ఫిరంగి గుండ్లతో\nగుండెలు + అదరన్ = గుండెలు అదిరిపోయేలా\nదేహపంజరము = శరీరమనే పంజరం\nడిల్లగన్ = కృశించిపోయేలా\nజల్లెడరీతిన్ = జల్లెడలాగా (తూట్లు పడేలా)\nమార్చినన్ = చేసినా\nసొలసియు = అలసిపోయి కూడా\nనిస్సురుస్సురు + అని = నిట్టూర్పులు విడుస్తూ (ఆయాసపడినా)\nస్రుక్కఁడు = కుంగిపోడు\nవైరి చేతికిన్ = శత్రువుల చేతికి\nచిక్కఁడు = చిక్కడు\nబలవత్ + అరి ప్రభంజనుఁడు = బలవంతులైన శత్రువులను పెనుగాలిలా చెదరగొట్టేవాడు\nభారతవీరుఁడు = భారతీయ వీరుడు\nమాటలు + ఏటికిన్ = (ఇంక) మాటలెందుకు?\nభావం: ప్రళయకాల మేఘాలు కురిసినట్లు ఆంగ్లేయుల ఫిరంగి గుండ్లు కురిసి గుండెలు అదిరేలా శరీరాన్ని జల్లెడలా తూట్లు పొడిచినా భారతవీరుడు అలసిపోయినా కుంగిపోడు, శత్రువులకు చిక్కడు. బలవంతులైన శత్రువులను పెనుగాలిలా చెదరగొట్టే భారత వీరుని గురించి ఇంకా చెప్పాలా?')
q(2, 8, 'ఆంగ్లేయుల నిరంకుశత్వ పాలనలో భారతీయుల పరిస్థితిని మీ సొంతమాటల్లో రాయండి.',
  '1) ఆర్థిక దోపిడీ: ఆంగ్లేయులు భారతదేశ సంపదను, ముడిసరుకులను ఇంగ్లండుకు తరలించారు; అన్నవస్త్రాలు దోచుకుని ప్రజలను పేదలను చేశారు.\n2) కరువులు, పన్నులు: అధిక పన్నులు, భూమి శిస్తుల భారంతో రైతులు అల్లాడారు; తరచు కరువులతో లక్షలాది మంది మరణించారు.\n3) కుటీర పరిశ్రమల నాశనం: చేనేత వంటి కులవృత్తులు దెబ్బతిని కళాకారులు నిరుద్యోగులయ్యారు.\n4) బానిస మనస్తత్వం: భారతీయులను ‘వట్టి సేవకులు’గా చూశారు; బానిసత్వాన్ని ఉగ్గుపాలతో పోసినట్లు అలవాటు చేశారు; మత్తు పదార్థాలు అలవాటు చేశారు.\n5) నిరంకుశ చట్టాలు: రౌలట్ చట్టం వంటి నల్ల చట్టాలతో విచారణ లేకుండా జైళ్ళలో పెట్టారు; సభలు, పత్రికలపై ఆంక్షలు.\n6) హింస: జలియన్‌వాలా బాగ్‌లో నిరాయుధ ప్రజలపై కాల్పులు; పసిపిల్లలను ఎండలో నడిపించడం, పొట్టపై పాకించడం వంటి చిత్రహింసలు.\n7) కృతఘ్నత: మొదటి ప్రపంచ యుద్ధంలో ఆంగ్లేయుల కోసం ప్రాణాలొడ్డిన భారతీయులకు అవమానమే బహుమతి.\nముగింపు: ఈ అణచివేతే భారతీయుల్లో స్వాతంత్ర్య కాంక్షను రగిలించింది.')
q(2, 8, 'స్వాతంత్ర్య ఉద్యమంలో తెలుగు నేలపై పోరాడిన యోధుల జీవితాలను ప్రస్తావించండి.',
  '1) అల్లూరి సీతారామరాజు: విశాఖ మన్యంలో గిరిజనులను ఏకం చేసి ఆంగ్లేయులపై సాయుధ పోరాటం (రంప తిరుగుబాటు 1922–24) చేశారు; 1924లో ప్రాణత్యాగం చేశారు – ‘మన్యం వీరుడు’.\n2) టంగుటూరి ప్రకాశం పంతులు: సైమన్ కమిషన్‌కు వ్యతిరేకంగా మద్రాసులో తుపాకీకి గుండె చూపిన ధీరుడు – ‘ఆంధ్ర కేసరి’; ఆంధ్ర రాష్ట్ర తొలి ముఖ్యమంత్రి.\n3) దుగ్గిరాల గోపాలకృష్ణయ్య: చీరాల–పేరాల ఉద్యమం నడిపారు – ‘ఆంధ్రరత్న’.\n4) కన్నెగంటి హనుమంతు: పల్నాడులో పుల్లరి (అటవీ పన్ను) వ్యతిరేక సత్యాగ్రహం నడిపి ప్రాణాలర్పించారు.\n5) పొట్టి శ్రీరాములు: గాంధీజీ అనుచరుడు, ఉప్పు సత్యాగ్రహంలో పాల్గొన్నారు; తర్వాత ఆంధ్ర రాష్ట్రం కోసం ఆమరణ నిరాహార దీక్షతో ప్రాణత్యాగం.\n6) పింగళి వెంకయ్య: మన జాతీయ పతాక రూపకర్త.\n7) దుర్గాబాయి దేశ్‌ముఖ్, బులుసు సాంబమూర్తి, అయ్యదేవర కాళేశ్వరరావు వంటి ఎందరో పాల్గొన్నారు.\nముగింపు: తెలుగు యోధుల త్యాగాలు స్వాతంత్ర్య పోరాటంలో చిరస్మరణీయం.')
q(2, 8, 'ఆంగ్లేయుల దురాగతాలను వ్యతిరేకిస్తూ భారత వీరుడి ఏకపాత్రాభినయాన్ని రాయండి.',
  '(రంగంపై ఒక భారత సైనికుడు – చేతిలో జెండా)\nఏమిటీ అన్యాయం? ఏమిటీ దౌర్జన్యం? ఓ తెల్లదొరల్లారా! వినండి!\nయూరప్ యుద్ధభూమిలో మీ కిరీటం కోసం మంచుగడ్డలపై పడుకున్నాం, బురదనీరు తాగాం, ఫిరంగి గుండ్లకు గుండెలు చూపాం. శత్రువుకు వెన్ను చూపని సింహాలం మేం! మీ జెండాను గెలిపించాం!\nదానికి మీరిచ్చిన బహుమతి ఏమిటి? రౌలట్ చట్టం అనే గాలం! విచారణ లేకుండా జైళ్ళు! జలియన్‌వాలా బాగ్‌లో పండుగ చేసుకుంటున్న నిరాయుధ తల్లులు, పసిపిల్లలపై తూటాల వర్షం! (ఆవేశంతో) ఆ బావిలో పడి చనిపోయిన నా సోదరుల ఆర్తనాదాలు ఇంకా నా చెవుల్లో మారుమోగుతున్నాయి!\nమమ్మల్ని ‘వట్టి సేవకులు’ అంటారా? మా అన్నవస్త్రాలు దోచి, పన్నులతో పీల్చి, కరువులకు బలిచేసి నాగరికులమని గర్వపడతారా?\n(దృఢంగా) గుర్తుంచుకోండి! ఈ పాపం ఊరికే పోదు – వడ్డీతో సహా అనుభవిస్తారు. భారతమాత బిడ్డలం మేం – మా రక్తంలో స్వాతంత్ర్య కాంక్ష రగులుతోంది. మా భూమి నుండి మిమ్మల్ని తరిమే వరకు విశ్రమించం!\nవందేమాతరం! భారత్ మాతా కీ జై!')
m(2, 'మూగజీవాలను హింసించుట మహా పాతకము. (గీత గీసిన పదం: పాతకము) సరైన వ్యుత్పత్త్యర్థం గుర్తించండి.', ['పతనమునకు కారణం అగునది', 'అభివృద్ధి చేయునది', 'పాపం లేనిది', 'పుణ్యం ఇచ్చేది'], 0, 'పాతకము – పతనానికి (నరకానికి) కారణమయ్యేది – పాపం.', mk=2)
m(2, 'హిమాలయాలు నీహారముతో కప్పబడి ఉంటాయి. (గీత గీసిన పదం: నీహారము) సరైన వ్యుత్పత్త్యర్థం గుర్తించండి.', ['శరీరంతో కప్పబడునది', 'నీటిలో కరుగునది', 'అగ్నిచే మిక్కిలి దహింపబడునది', 'వాయువులో కలిసిపోయేది'], 2, 'నీహారము – అగ్ని (వేడి)చే నిశ్శేషంగా హరింపబడునది (కరిగిపోయేది) – మంచు.', mk=2)
m(2, 'దేవతల పానీయము అమృతము. (గీత గీసిన పదం: పానీయము) సరైన వ్యుత్పత్త్యర్థం గుర్తించండి.', ['పానము చేయబడేది', 'మరణంతో కూడినది', 'నీటిని ఇచ్చునది', 'ద్రవమై ఉండునది'], 0, mk=2)
q(2, 2, 'అలంకారాలను గుర్తించి, లక్షణం రాయండి: “దుఃఖ సముద్రము భారతీయ హృద్ద్వారము సొచ్చి యగ్నివలె జ్వాలలు వీచుచునున్న దెంతయున్”',
  '1) రూపకాలంకారం: “దుఃఖ సముద్రము” – ఉపమేయమైన దుఃఖానికి, ఉపమానమైన సముద్రానికి అభేదం చెప్పబడింది. (లక్షణం: ఉపమేయ ఉపమానాలకు అభేదం చెప్పడం.)\n2) ఉపమాలంకారం: “అగ్నివలె జ్వాలలు” – దుఃఖాన్ని అగ్నితో పోల్చారు; ‘వలె’ ఉపమావాచకం. (లక్షణం: ఉపమాన ఉపమేయాలకు చక్కని పోలిక చెప్పడం.)')
q(2, 2, 'పద్య పాదానికి గణవిభజన చేసి గురు, లఘువులు గుర్తించి, ఏ పద్యపాదమో రాయండి: “రౌలటుశాసనంబు సమరంబున గెల్చినదాని కంకుగా”',
  'రౌలటు | శాసనం | బుసమ | రంబున | గెల్చిన | దానికం | కుగా\nU I I | U I U | I I I | U I I | U I I | U I U | I U\nభ | ర | న | భ | భ | ర | వ\nఇది ఉత్పలమాల పద్యపాదం (యతి – 10వ అక్షరం: రౌ – రం).')
q(2, 2, 'పద్య పాదానికి గణవిభజన చేసి గురు, లఘువులు గుర్తించి, ఏ పద్యపాదమో రాయండి: “జలియను బాగులో జనుల జంపిన రక్తము వర్షపాతముం”',
  'జలియ | నుబాగు | లోజను | లజంపి | నరక్త | మువర్ష | పాతముం\nI I I | I U I | U I I | I U I | I U I | I U I | U I U\nన | జ | భ | జ | జ | జ | ర\nఇది చంపకమాల పద్యపాదం (యతి – 11వ అక్షరం: జ – జం).')
ITEMS = B.items
